  personalization: {
    base: character_traits × context, // 基于角色特征与情境的笛卡尔积，表示多样化组合
    require: diversify(behavior, appearance, language) ∧ conform(character_traits), // 多样化行为/外貌/语言，并符合角色特征
    immersion: role ∈ world_situation // 将角色代入世界情境中
