etVolume]=useState(0.8);useEffect(()=>{try{localStorage.setItem('prism_name',charName)}catch(e){}},[charName]);useEffect(()=>{const initMusic=async()=>{let aiSong=rawSong.replace(/[《》""'']/g,'');if(aiSong&&!aiSong.startsWith('$')){try{let retries=30;while(typeof window.Music==='undefined'&&retries>0){await new Promise(r=>setTimeout(r,100));retries--;}if(typeof window.Music!=='undefined'&&window.Music.SearchMusic){const res=await window.Music.SearchMusic(aiSong);if(res&&res.Url){setSongData(res);if(audioRef.current){audioRef.current.src=res.Url;audioRef.current.load();}}}}catch(e){}}setIsLoading(false)};initMusic()},[]);useEffect(()=>{if(audioRef.current)audioRef.current.volume=volume},[volume]);useEffect(()=>{const audio=audioRef.current;if(!audio)return;const updateProgress=()=>setProgress(audio.currentTime);const setAudioDuration=()=>setDuration(audio.duration);const handleEnd=()=>setIsPlaying(false);audio.addEventListener('timeupdate',updateProgress);audio.addEventListener('loadedmetadata',setAudioDuration);audio.addEventListener('ended',handleEnd);return()=>{audio.removeEventListener('timeupdate',updateProgress);audio.removeEventListener('loadedmetadata',setAudioDuration);audio.removeEventListener('ended',handleEnd)}},[]);const togglePlay=(e)=>{if(e)e.stopPropagation();if(!audioRef.current||!songData?.Url)return;if(isPlaying){audioRef.current.pause();setIsPlaying(false)}else{const p=audioRef.current.play();if(p!==undefined){p.then(()=>setIsPlaying(true)).catch(err=>{setIsPlaying(false)})}else{setIsPlaying(true)}}};const handleSeek=(e)=>{if(audioRef.current){const newTime=Number(e.target.value);audioRef.current.currentTime=newTime;setProgress(newTime)}};const handleMouseMove=(e)=>{const rect=e.currentTarget.getBoundingClientRect();e.currentTarget.style.setProperty('--mouse-x',`${e.clientX-rect.left}px`);e.currentTarget.style.setProperty('--mouse-y',`${e.clientY-rect.top}px`)};const handleTriggerClick=(e)=>{if(!isExpanded)return;const rect=e.currentTarget.getBound